use clap::Parser;
use mapgen::export::{ExportOptions, export_world, world_dir_name};
use mapgen::generation::{GenerateOptions, generate_with_progress};
use mapgen::preset::Preset;
use mapgen::request::{self, Limits, WorldRequest};
use std::error::Error;
use std::path::PathBuf;
use std::process::ExitCode;

/// Procedural planet map generator.
///
/// Every omitted option comes from the planet preset or is chosen randomly;
/// the chosen values are printed so any world can be regenerated by passing
/// them back explicitly.
#[derive(Parser)]
#[command(version, about)]
struct Args {
    /// Planet preset: a built-in name (terran, volcanic, frozen, caustic,
    /// barren) or a path to a .toml preset file [default: random built-in]
    #[arg(long)]
    planet: Option<String>,

    /// List the built-in planet presets and exit
    #[arg(long)]
    list_planets: bool,

    /// Waterline shift in [-1, 1]; positive means more ocean [default: random in 0.10..0.40]
    #[arg(long, allow_negative_numbers = true, value_parser = parse_in(request::SEA_LEVEL),
          conflicts_with = "land_fraction")]
    sea_level: Option<f32>,

    /// Share of the surface that is land, in [0, 1] (Earth: 0.29); the sea
    /// level is computed to match it. Replaces --sea-level
    #[arg(long, value_parser = parse_in(request::LAND_FRACTION))]
    land_fraction: Option<f32>,

    /// Share of mountain chains that become volcanic, in [0, 1] [default: random]
    #[arg(long, value_parser = parse_in(request::VOLCANIC))]
    volcanic: Option<f32>,

    /// Equatorial circumference in km [default: random in 20000..80000]
    #[arg(long, value_parser = parse_in(request::CIRCUMFERENCE_KM))]
    circumference: Option<f32>,

    /// Axial tilt in degrees, in [0, 90] [default: random in 5..40]
    #[arg(long, value_parser = parse_in(request::AXIAL_TILT_DEG))]
    axial_tilt: Option<f32>,

    /// Hydraulic erosion strength in [0, 5]; 0 disables erosion [default: 1]
    #[arg(long, value_parser = parse_in(request::EROSION))]
    erosion: Option<f32>,

    /// Noise seed [default: random]
    #[arg(long)]
    seed: Option<u32>,

    /// Map width in pixels
    #[arg(long, default_value_t = request::fallback::WIDTH,
          value_parser = clap::value_parser!(u32).range(2..=16384))]
    width: u32,

    /// Map height in pixels
    #[arg(long, default_value_t = request::fallback::HEIGHT,
          value_parser = clap::value_parser!(u32).range(2..=16384))]
    height: u32,

    /// Directory that receives the generated worlds
    #[arg(long, default_value = "worlds")]
    out_dir: PathBuf,

    /// Skip the raw_data/ export (world.json and the layer PNGs)
    #[arg(long)]
    no_raw_data: bool,

    /// Skip the diagnostic noise maps
    #[arg(long)]
    no_noise_maps: bool,
}

/// Builds a clap value parser that accepts an `f32` within `limits`.
fn parse_in(limits: Limits) -> impl Fn(&str) -> Result<f32, String> + Clone {
    move |s| {
        let v: f32 = s.parse().map_err(|e| format!("{e}"))?;
        if limits.contains(v) {
            Ok(v)
        } else {
            Err(format!("must be between {} and {}", limits.min, limits.max))
        }
    }
}

fn main() -> ExitCode {
    match run(Args::parse()) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("error: {e}");
            ExitCode::FAILURE
        }
    }
}

fn run(args: Args) -> Result<(), Box<dyn Error>> {
    if args.list_planets {
        for preset in Preset::built_in() {
            println!("{:10} {}", preset.name, preset.description);
        }
        return Ok(());
    }

    let request = WorldRequest {
        planet: args.planet,
        seed: args.seed,
        sea_level: args.sea_level,
        land_fraction: args.land_fraction,
        volcanic: args.volcanic,
        circumference_km: args.circumference,
        axial_tilt_deg: args.axial_tilt,
        erosion: args.erosion,
        width: Some(args.width),
        height: Some(args.height),
    };
    let resolved = request.resolve(&mut rand::rng())?;
    let p = &resolved.params;
    println!(
        "Parameters → planet={} seed={} sea_level={:.2} volcanic={:.2} \
         circumference={:.0} km tilt={:.1}° gravity≈{:.2}g",
        p.planet.name,
        p.seed,
        p.sea_level,
        p.volcanic_intensity,
        p.circumference_km,
        p.axial_tilt_deg,
        p.gravity_modifier()
    );

    // Debug layers only feed the noise maps: skip them (and their memory)
    // when the maps are not exported.
    let generated = generate_with_progress(
        p,
        GenerateOptions {
            debug_layers: !args.no_noise_maps,
        },
        |_| {},
    );
    let dir = args.out_dir.join(world_dir_name(&generated.world));
    let options = ExportOptions {
        raw_data: !args.no_raw_data,
        noise_maps: !args.no_noise_maps,
    };
    export_world(&generated, &dir, options)?;

    println!("World generated → {}/", dir.display());
    // Exact values (the summary above is rounded) so the world can be regenerated.
    println!(
        "Reproduce with: --planet {} --seed {} --sea-level {} --volcanic {} \
         --circumference {} --axial-tilt {} --erosion {}",
        resolved.planet_spec,
        p.seed,
        p.sea_level,
        p.volcanic_intensity,
        p.circumference_km,
        p.axial_tilt_deg,
        p.erosion
    );
    Ok(())
}
